// Assembles src/markdownVendor.generated.ts and THIRD_PARTY_NOTICES.txt from
// the built runtime IIFE and the vendored CSS/fonts. Invoked by
// scripts/build-markdown-vendor.sh after `bun build`.
import { execSync } from "node:child_process";
import { createHash } from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const vendorDir = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(vendorDir, "..", "..");
const outTs = path.join(repoRoot, "src", "markdownVendor.generated.ts");
const outNotices = path.join(vendorDir, "THIRD_PARTY_NOTICES.txt");
const runtimeJs = path.join(vendorDir, "dist", "markdown-runtime.js");

const HEADER = "// Generated by scripts/build-markdown-vendor.sh — do not edit.\n";

function katexCss() {
  const cssPath = path.join(
    vendorDir,
    "node_modules",
    "katex",
    "dist",
    "katex.min.css",
  );
  let css = fs.readFileSync(cssPath, "utf8");
  // Inline every woff2 font as a data: URL and drop the woff/ttf fallbacks.
  css = css.replace(
    /src:url\(fonts\/([\w.-]+)\.woff2\) format\("woff2"\)(?:,url\(fonts\/[\w.-]+\.(?:woff|ttf)\) format\("(?:woff|truetype)"\))*/g,
    (m, name) => {
      const fontPath = path.join(
        vendorDir,
        "node_modules",
        "katex",
        "dist",
        "fonts",
        `${name}.woff2`,
      );
      const b64 = fs.readFileSync(fontPath).toString("base64");
      return `src:url(data:font/woff2;base64,${b64}) format("woff2")`;
    },
  );
  return css;
}

function githubMarkdownCss() {
  const cssPath = path.join(
    vendorDir,
    "node_modules",
    "github-markdown-css",
    "github-markdown.css",
  );
  return fs.readFileSync(cssPath, "utf8");
}

function directDeps() {
  const pkg = JSON.parse(
    fs.readFileSync(path.join(vendorDir, "package.json"), "utf8"),
  );
  return Object.keys(pkg.dependencies);
}

function collectPackages() {
  const seen = new Map();
  const queue = [...directDeps()];
  while (queue.length > 0) {
    const name = queue.shift();
    if (seen.has(name)) continue;
    let dir = path.join(vendorDir, "node_modules", name);
    if (!fs.existsSync(dir)) {
      dir = path.join(
        vendorDir,
        "node_modules",
        ".bun",
        `${name.replace("/", "+")}@*`,
        "node_modules",
        name,
      );
      const matches = execSync(`ls -d ${dir} 2>/dev/null || true`)
        .toString()
        .trim()
        .split("\n")
        .filter(Boolean);
      if (matches.length === 0) continue;
      dir = matches[0];
    }
    const pkgPath = path.join(dir, "package.json");
    if (!fs.existsSync(pkgPath)) continue;
    const pkg = JSON.parse(fs.readFileSync(pkgPath, "utf8"));
    seen.set(name, { pkg, dir });
    for (const dep of Object.keys(pkg.dependencies || {})) queue.push(dep);
  }
  return seen;
}

function licenseText(dir) {
  for (const f of fs.readdirSync(dir)) {
    if (/^(licen[sc]e|copying|unlicense)/i.test(f)) {
      return fs.readFileSync(path.join(dir, f), "utf8").trim();
    }
  }
  return "(license text not shipped in package)";
}

function writeNotices() {
  const pkgs = collectPackages();
  const parts = [
    "Aed Markdown Preview — third-party software notices",
    `Generated ${new Date().toISOString().slice(0, 10)} by scripts/build-markdown-vendor.sh`,
    "",
    "Vendored packages (name@version — license):",
    "",
  ];
  for (const [name, { pkg, dir }] of [...pkgs].sort(([a], [b]) =>
    a.localeCompare(b),
  )) {
    const license =
      pkg.license ||
      (pkg.licenses || []).map((l) => l.type || l).join(" OR ") ||
      "unknown";
    parts.push(`${name}@${pkg.version} — ${license}`);
    parts.push("-".repeat(60));
    parts.push(licenseText(dir));
    parts.push("");
  }
  fs.writeFileSync(outNotices, parts.join("\n"));
}

// Stamp a build id (sha256 of the inputs) into the runtime so the test suite
// can prove the committed dist file and MARKDOWN_RUNTIME_JS come from the
// same build.
const buildId = createHash("sha256")
  .update(fs.readFileSync(path.join(vendorDir, "entry.mjs")))
  .update(fs.readFileSync(path.join(vendorDir, "page.mjs")))
  .update(fs.readFileSync(path.join(vendorDir, "bun.lock")))
  .digest("hex")
  .slice(0, 16);

// The test suite imports the runtime artifact directly (QuickJS disables the
// Function constructor, so the string can't be eval'd): give it types.
fs.writeFileSync(
  path.join(vendorDir, "dist", "markdown-runtime.d.ts"),
  "declare global {\n  var AedMarkdown: { renderMarkdown(src: string): { html: string; headings: { level: number; text: string; id: string }[] }; buildId: string };\n}\nexport {};\n",
);

const js =
  fs.readFileSync(runtimeJs, "utf8") +
  `\n;globalThis.AedMarkdown.buildId=${JSON.stringify(buildId)};\n`;
fs.writeFileSync(runtimeJs, js);

const out =
  HEADER +
  `export const MARKDOWN_RUNTIME_JS = ${JSON.stringify(js)};\n\n` +
  `export const KATEX_CSS = ${JSON.stringify(katexCss())};\n\n` +
  `export const GITHUB_MARKDOWN_CSS = ${JSON.stringify(githubMarkdownCss())};\n`;
fs.writeFileSync(outTs, out);
writeNotices();
console.log(
  `wrote ${path.relative(repoRoot, outTs)} (${out.length} bytes) and ${path.relative(vendorDir, outNotices)}`,
);
